static int
gk_species_bflux_mom_idx(
  struct gk_boundary_fluxes *bflux, int dir, enum gkyl_edge_loc edge,
  enum gkyl_distribution_moments mom_type
)
{
  // Given a direction 'dir', the edge 'edge', and the name of a moment
