static int *
bflux_unionize_moms(
  int num_add_moms, enum gkyl_distribution_moments add_moms[BFLUX_MAX_MOM_NAMES], int *num_moms,
  enum gkyl_distribution_moments moms[BFLUX_MAX_MOM_NAMES]
)
{
  // Check if each of the num_add_moms moments in add_moms is included in the
  // moms list of num_moms moments. If it's not, include it and increment
  // num_moms. Return a list of the indices of each add_moms in the moms list.
  int *add_mom_idx = gkyl_malloc(num_add_moms * sizeof(int));
  int num_moms_base = num_moms[0];
  for (int i = 0; i < num_add_moms; i++) {
    enum gkyl_distribution_moments mom_name = add_moms[i];
    bool included = false;
    for (int j = 0; j < num_moms_base; j++) {
      if (mom_name == moms[j]) {
        included = true;
        add_mom_idx[i] = j;
        break;
      }
    }

    if (!included) {
      add_mom_idx[i] = num_moms[0];
      moms[num_moms[0]] = mom_name;
      num_moms[0] += 1;
    }
  }
  return add_mom_idx;
}

void
gk_species_bflux_init(
  struct gkyl_gyrokinetic_app *app, void *species, struct gk_boundary_fluxes *bflux,
  enum gkyl_species_bflux_type bflux_type, struct gkyl_phase_diagnostics_inp add_moms_inp
